(()=>{const run=()=>{const grid=document.getElementById('sessions-grid');if(grid&&grid.children.length&&!document.getElementById('kirsty-session-26aug')){const card=document.createElement('div');card.className='card session-card';card.id='kirsty-session-26aug';card.innerHTML='<span class="pill">26 Aug 2026 · COMPLETED</span><h3>Progress review, Compass and attention</h3><p><b>Session:</b> Had a really good session with Kirsty. We talked through Darren\'s Compass and how it keeps the diary, therapy work and progress together as it continues to grow. Kirsty was impressed with what we have built and how clearly it shows the progress being made.</p><p><b>What we talked about:</b> Reviewed the week and the progress so far. We also touched on the possibility that some of my attention/concentration patterns could fit with ADHD or being on the spectrum. Kirsty cannot diagnose this, so this is not being recorded as a diagnosis, but she can keep those patterns in mind in how we work together.</p><p><b>Homework:</b> The Happiness Trap card Kirsty gave me is <b>The Self-Esteem Trap</b>, with the practice <b>Self-Acceptance and Self-Compassion</b>. The idea is to stop fighting recurring “not good enough” stories by trying to force a positive self-image. Instead, notice both positive and negative self-stories without getting too attached to either, acknowledge when I am hurting, and treat myself with kindness and care.</p><p><b>Next session:</b> Monday 14 September 2026 at 13:00.</p>';grid.prepend(card);}const recent=document.getElementById('recent-wins');if(recent&&!document.getElementById('progress-kirsty-26aug')){const x=document.createElement('div');x.id='progress-kirsty-26aug';x.className='item';x.innerHTML='<span class="dot"></span><div><div>Kirsty was impressed with Darren\'s Compass and how it shows the progress being made over time.</div><small>The app is becoming a useful living record of diary, therapy work and progress.</small></div>';recent.prepend(x);}const lib=document.getElementById('library-grid');if(lib&&lib.children.length&&!document.getElementById('homework-self-acceptance')){const c=document.createElement('div');c.className='card';c.id='homework-self-acceptance';c.innerHTML='<span class="pill">CURRENT HOMEWORK</span><h3>The Self-Esteem Trap</h3><p><b>Practice: Self-Acceptance and Self-Compassion</b></p><p>Accept myself as I am, including strengths and weaknesses, successes and failures. Hold both positive and negative self-stories lightly rather than getting caught up in either.</p><p>When I notice I am hurting or the “not good enough” story turns up, acknowledge it and offer myself kind, caring support rather than trying to fight it by forcing positive thoughts.</p><small>Happiness Trap flash card from Kirsty · 26 Aug 2026</small>';lib.prepend(c);}const wt=document.getElementById('week-title');if(wt)wt.textContent='Self-Acceptance and Self-Compassion';const ws=document.getElementById('week-summary');if(ws)ws.textContent='This week is about noticing the “not good enough” story without getting hooked by it, accepting both strengths and weaknesses, and responding to myself with kindness rather than trying to force a positive self-image.';const asks=document.getElementById('week-asks');if(asks)asks.innerHTML='<div class="item"><span class="dot"></span><div><div>Notice when the “not good enough” story shows up</div><span class="status open">open</span></div></div><div class="item"><span class="dot"></span><div><div>Hold both positive and negative self-stories lightly</div><span class="status open">open</span></div></div><div class="item"><span class="dot"></span><div><div>When I am hurting, respond with kindness and care</div><span class="status open">open</span></div></div>';const talk=document.getElementById('week-discussion');if(talk)talk.innerHTML='<div class="item"><span class="dot"></span><div><div>When did the “not good enough” story show up?</div></div></div><div class="item"><span class="dot"></span><div><div>Was I able to notice it without arguing with it?</div></div></div><div class="item"><span class="dot"></span><div><div>What did self-compassion actually look like in the moment?</div></div></div>';const next=document.getElementById('next-appointment');if(next)next.textContent='14 Sep 2026';const nt=document.getElementById('next-appointment-time');if(nt)nt.textContent='13:00';const updated=document.getElementById('updated');if(updated)updated.textContent='Updated 29 August 2026';};let n=0;const t=setInterval(()=>{run();if(++n>16)clearInterval(t)},250);})();